def _with_oc(pdf: pikepdf.Pdf, default: pikepdf.Dictionary, configs: list[pikepdf.Dictionary] | None = None) -> None:
    """Give ``pdf`` two optional content groups and the configurations ``default`` and ``configs``; the strings
    "one" and "two" in an /Order are replaced by the groups."""
    groups = [
        pdf.make_indirect(pikepdf.Dictionary(Type=pikepdf.Name.OCG, Name=pikepdf.String(n))) for n in ("one", "two")
    ]
    if "/Order" in default:
        default["/Order"] = pikepdf.Array([groups[0] if str(o) == "one" else groups[1] for o in default.Order])
    props = pikepdf.Dictionary(OCGs=pikepdf.Array(groups), D=default)
    if configs is not None:
        props["/Configs"] = pikepdf.Array(configs)
    pdf.Root["/OCProperties"] = props


def _with_annot(pdf: pikepdf.Pdf, subtype: str, rect: list[float], **extra: pikepdf.Object) -> None:
    annot = pikepdf.Dictionary(Type=pikepdf.Name.Annot, Subtype=pikepdf.Name(f"/{subtype}"), Rect=rect, F=4)
    for key, value in extra.items():
        annot[f"/{key}"] = value
    pdf.pages[0].obj["/Annots"] = pikepdf.Array([pdf.make_indirect(annot)])


def _trapped_true() -> pikepdf.Pdf:
    """x4-good saying it is trapped, as a TrapNet annotation requires (6.9)."""
    return _x4_meta(("<pdf:Trapped>False<", "<pdf:Trapped>True<"), info={"Trapped": pikepdf.Name("/True")})


def _trapnet(pdf: pikepdf.Pdf, **extra: pikepdf.Object) -> pikepdf.Pdf:
    """``pdf`` with a TrapNet annotation outside the media box, as trap networks are exempt from 6.17's placing."""
    appearance = pdf.make_stream(b"", Type=pikepdf.Name.XObject, Subtype=pikepdf.Name.Form, BBox=[0, 0, 1, 1])
    appearance["/PCM"] = extra.pop("PCM", pikepdf.Name.DeviceCMYK)
    entries = {
        "LastModified": pikepdf.String("D:20261125120000Z"),
        "AP": pikepdf.Dictionary(N=pdf.make_indirect(appearance)),
    }
    _with_annot(pdf, "TrapNet", [0.0, 0.0, 1.0, 1.0], **entries, **extra)
    return pdf


def _x4_page_object_fixtures() -> dict[str, pikepdf.Pdf]:
    """The negatives of 6.24, 6.17 and 6.9's TrapNet rows (expected.toml says what each raises)."""
    name, text = pikepdf.Name, pikepdf.String
    inside = [100.0, 100.0, 120.0, 120.0]  # inside x4-good's trim and bleed boxes
    return {
        "x4-oc-unnamed": _x4_with(lambda p: _with_oc(p, pikepdf.Dictionary())),
        "x4-oc-same-name": _x4_with(
            lambda p: _with_oc(p, pikepdf.Dictionary(Name=text("Print")), [pikepdf.Dictionary(Name=text("Print"))])
        ),
        "x4-oc-order-incomplete": _x4_with(
            lambda p: _with_oc(p, pikepdf.Dictionary(Name=text("Print"), Order=pikepdf.Array([text("one")])))
        ),
        "x4-oc-as": _x4_with(lambda p: _with_oc(p, pikepdf.Dictionary(Name=text("Print"), AS=pikepdf.Array()))),
        "x4-annot-inside-bleed": _x4_with(lambda p: _with_annot(p, "Text", inside)),
        "x4-printermark-inside-trim": _x4_with(lambda p: _with_annot(p, "PrinterMark", inside)),
        "x4-trapnet-untrapped": _trapnet(_x4_good()),
        "x4-trapnet-font-fauxing": _trapnet(_trapped_true(), FontFauxing=pikepdf.Array([name.Helvetica])),
        "x4-trapnet-pcm-rgb": _trapnet(_trapped_true(), PCM=name.DeviceRGB),
    }


def fixtures() -> dict[str, pikepdf.Pdf | bytes]:
    good = build()
    a5 = {
        "MediaBox": [0, 0, 148 * MM, 210 * MM],
        "TrimBox": [0, 0, 148 * MM, 210 * MM],
        "BleedBox": [0, 0, 148 * MM, 210 * MM],
    }
    return {
        # Passes every layer, including veraPDF PDF/A-2b.
        "good": good,
        # What a default LaTeX build looks like: boxes and metadata missing, no output intent.
        "plain": build(boxes={"MediaBox": [0, 0, MEDIA_W, MEDIA_H]}, output_intent=False, xmp=False, trapped=False),
        # Good in every way but the trim size: an A5 page where an A6 card was expected.
        "wrong-size": build(boxes=a5),
        # PDF/A-clean (sRGB intent) with a DeviceRGB raster: the colour-space check must fire.
        "rgb-image": _with_image("rgb", size=500, space=pikepdf.Name.DeviceRGB, components=3, placed_pt=100),
        # A 4x4 grey raster stretched over 100 pt: far below any print resolution.
        "low-dpi-image": _with_image("low", size=4, space=pikepdf.Name.DeviceGray, components=1, placed_pt=100),
        # Solid 400% ink: above the 300% ceiling. (DeviceCMYK without a CMYK intent also fails PDF/A.)
        "heavy-ink": build(GOOD_CONTENT + b" 1 1 1 1 k 30 30 80 80 re f"),
        # Cyan text under overprint: not K-only, and overprint on non-K content.
        "cyan-text": _with_text(b"1 0 0 0 k (cyan) Tj", overprint=True),
        # 100% K text under overprint: the normal case, which must pass --k-only-text cleanly.
        "black-text": _with_text(b"0 0 0 1 k (black) Tj", overprint=True),
        # Small text in a built black, which mis-registers.
        "rich-black-text": _with_text(b"0.6 0.5 0.4 0.9 k (rich) Tj"),
        # A character the font has no glyph for: code 0 in an Identity-H font is .notdef, printed as a box.
        "notdef-text": _with_text(b"<00410000> Tj", type0=True),
        # 4 pt text, below any sensible floor.
        "small-text": _with_text(b"0 g (tiny) Tj", size=4),
        # A zero-width stroke, the thinnest line the device can draw.
        "hairline": build(GOOD_CONTENT + b" 0 w 40 40 m 200 40 l S"),
        # Text one millimetre inside the trim edge.
        "edge-text": _with_text(b"0 g (edge) Tj", at=(BLEED + 1 * MM, 200)),
        # Mid-grey text on a slightly lighter panel: a small L* difference.
        "low-contrast": _with_text(
            b"0.8 g (faint) Tj",
            prefix=b" 0.9 g %f %f 200 60 re f" % (BLEED + 20, BLEED + 10),
            at=(BLEED + 30, BLEED + 30),
        ),
        # Black text on bare paper: the opposite.
        "high-contrast": _with_text(b"0 g (clear) Tj"),
        # White text set to overprint: it adds no ink and vanishes on press.
        "white-overprint": _with_text(b"1 g (hidden) Tj", overprint=True),
        # Text in an embedded font: the fonts check passes.
        "embedded-text": _with_text(b"0 g (embedded) Tj", kind="embedded"),
        # Text in a Type 3 font: a warning.
        "type3-text": _with_text(b"0 g (A) Tj", kind="type3"),
        # A Pantone spot ink, and the registration colour used as if it were artwork.
        "spot-ink": _with_spot("PANTONE 185 C"),
        "registration-spot": _with_spot("All"),
        # A spot overprinting full cyan: 200% of ink, which a CMYK raster of the alternate would miss.
        "spot-overprint": _spot_overprint(),
        # Live transparency with the blend space declared RGB, matching the sRGB output intent; CMYK, mismatching it;
        # and not declared at all.
        "transparent-matching": _transparent("DeviceRGB"),
        "transparent-mismatch": _transparent("DeviceCMYK"),
        "transparent-undeclared": _transparent(None),
        # A page of another size after the card, and a three-page file for a multiple-of-four rule.
        "two-sizes": _multi_page([(148, 210)]),
        "three-pages": _multi_page([(105, 148), (105, 148)]),
        # A background that stops at the trim edge: every other check passes, and cutting leaves a white sliver.
        "no-bleed": build(
            b"0.9 g %f %f %f %f re f" % (BLEED, BLEED, TRIM_W, TRIM_H) + GOOD_CONTENT[GOOD_CONTENT.index(b" 0.2") :]
        ),
        # A three-page A6 interior: bleed on the outer, top and bottom edges only, the bound edge alternating by page.
        "book-interior": _book_interior(),
        # The good card on a larger sheet with crop marks in the margin: valid, but a bare-page printer rejects them.
        "crop-marks": _crop_marks(),
        # PDF/A metadata but no output intent: veraPDF fails on DeviceGray, and proof-pdf adds a hint.
        "no-output-intent": build(output_intent=False),
        # Genuine PDF/X-4: the positive base for the PDF/X checks (good.pdf is PDF/A-2b, and fails X-4).
        "x4-good": _x4_good(),
        # Its negatives, one defect each (tests/fixtures/pdfx/expected.toml says what each must raise).
        "x4-lzw": _x4_content(["LZWDecode"], _lzw(GOOD_X4_CONTENT)),
        # Saved with a stand-in key, renamed to /Filter in the bytes: qpdf would decode a Crypt filter it was given.
        "x4-crypt-filter": _x4_crypt(),
        "x4-filter-abbreviated": _x4_content(["Fl"], zlib.compress(GOOD_X4_CONTENT)),
        "x4-perms": _x4_perms(),
        **_x4_metadata_fixtures(),
        **_x4_intent_fixtures(),
        **_x4_box_fixtures(),
        **_x4_key_fixtures(),
        **_x4_page_object_fixtures(),
        **_x4_content_fixtures(),
        **_x4_colour_fixtures(),
    }


def render() -> dict[str, bytes]:
    """Every fixture as bytes, deterministically."""
    out: dict[str, bytes] = {}
    scratch = OUT.parent / ".build"
    scratch.mkdir(exist_ok=True)
    try:
        for name, pdf in fixtures().items():
            path = scratch / f"{name}.pdf"
            assert isinstance(pdf, pikepdf.Pdf)
            pdf.save(
                path,
                deterministic_id=True,
                min_version="1.7",
                compress_streams=False,
                object_stream_mode=pikepdf.ObjectStreamMode.disable,
            )
            out[name] = path.read_bytes()
        out["corrupt"] = out["good"][: len(out["good"]) // 2]  # truncated mid-file
        out.update(_x4_variants(out["x4-good"], scratch))
        assert out["x4-crypt-filter"].count(b"/Xilter /Crypt") == 1
        out["x4-crypt-filter"] = out["x4-crypt-filter"].replace(b"/Xilter /Crypt", b"/Filter /Crypt")
    finally:
        for f in scratch.glob("*.pdf"):
            f.unlink()
        scratch.rmdir()
    return out


def _x4_variants(good: bytes, scratch: pathlib.Path) -> dict[str, bytes]:
    """Negatives of x4-good made on its saved bytes, each change keeping every offset."""
    assert good.count(b"/ProofBox") == 2, "BaseFont and FontName"
    with pikepdf.open(io.BytesIO(good)) as pdf:
        path = scratch / "x4-encrypted.pdf"
        # RC4 (R4 without AES) derives everything from the ID and the passwords, and a static ID makes the bytes the
        # same every build (qpdf will not compute a deterministic ID for an encrypted file).
        pdf.save(path, static_id=True, encryption=pikepdf.Encryption(owner="", user="", R=4, aes=False, metadata=False))
        encrypted = path.read_bytes()
    return {
        # 6.6: a font name that decodes to bytes that are not UTF-8 (written escaped, as 6.6 also asks).
        "x4-name-not-utf8": good.replace(b"/ProofBox", b"/Proof#FF"),
        # 6.6: a font name holding UTF-8 bytes outside 33 to 126 written raw, not as #xx.
        "x4-name-unescaped": good.replace(b"/ProofBox", "/Pr\u00e9fBox".encode()),
        "x4-encrypted": encrypted,
        "x4-too-many-objects": _too_many_objects(good),
        # Damage to the file's own structure, each a same-length edit (ISO 32000-2 rules, checked at every level).
        "x4-no-header": _edit(good, b"%PDF-", b"%PXF-"),
        "x4-header-offset": b"junk\n" + good,
        "x4-truncated": good[: len(good) // 2],
        "x4-bad-xref": _edit(good, b"\nxref\n0 ", b"\nxreg\n0 "),
        "x4-no-root": _edit(good, b"/Root 1 0 R", b"/Rooo 1 0 R"),
        "x4-after-eof": good + b"<html>",
        "x4-many-updates": _many_updates(good, 1001),
        "x4-odd-hex": _edit(good, b"><b21aaa", b">< 21aaa"),
        "x4-octal-overflow": _edit(good, b"(Little-CMS testbed", b"(\\777le-CMS testbed", times=2),
        "x4-bad-name-escape": _edit(good, b"/ProofBox", b"/Proof#GG", times=2, every=True),
        "x4-duplicate-key": _edit(good, b"/CreationDate", b"/ModDate     "),
        "x4-no-eol-before-endstream": _edit(good, b"(PDF/X-4) Tj ET\nendstream", b"(PDF/X-4) Tj ET endstream"),
        "x4-unknown-filter": _edit(good, b"/FlateDecode", b"/FlateDecodX", times=2),
        "x4-damaged-object": _edit(good, b"2 0 obj\n<<", b"2 0 obj\n[<"),
        "x4-dangling-reference": _edit(good, b"/Info 2 0 R", b"/Info 2 5 R"),
        # 6.10.1 and 6.10.4: no catalog metadata, and no trailer /ID.
        "x4-no-xmp": _edit(good, b"<< /Metadata 3 0 R", b"<< /Metadatx 3 0 R"),
        "x4-no-trailer-id": _edit(good, b"/ID [", b"/IX ["),
        "x4-xmp-filtered": _compressed_xmp(good),
    }


def _edit(good: bytes, old: bytes, new: bytes, *, times: int = 1, every: bool = False) -> bytes:
    """``good`` with ``old`` (found exactly ``times`` times) replaced by same-length ``new``, once or every time."""
    assert len(old) == len(new) and good.count(old) == times, (old, good.count(old))
    return good.replace(old, new, -1 if every else 1)


def _many_updates(good: bytes, count: int) -> bytes:
    """``good`` followed by ``count`` empty incremental updates, each a table with no entries and a /Prev."""
    out = bytearray(good)
    trailer = good[good.rindex(b"trailer") + 7 : good.rindex(b"startxref")].strip()
    prev = int(good[good.rindex(b"startxref") + 9 :].split()[0])
    for _ in range(count):
        here = len(out)
        out += b"xref\n0 0\ntrailer\n" + trailer[:-2] + b" /Prev %d >>\nstartxref\n%d\n%%%%EOF\n" % (prev, here)
        prev = here
    return bytes(out)


def _compressed_xmp(good: bytes) -> bytes:
    """x4-good with its XMP (object 3) Flate-compressed in an incremental update: qpdf will not save it compressed."""
    with pikepdf.open(io.BytesIO(good)) as pdf:
        assert pdf.Root.Metadata.objgen == (3, 0)
        xmp = pdf.Root.Metadata.read_bytes()
    data = zlib.compress(xmp)
    obj = b"3 0 obj\n<< /Type /Metadata /Subtype /XML /Filter /FlateDecode /Length %d >>\nstream\n" % len(data)
    obj += data + b"\nendstream\nendobj\n"
    trailer = good[good.rindex(b"trailer") + 7 : good.rindex(b"startxref")].strip()
    prev = int(good[good.rindex(b"startxref") + 9 :].split()[0])
    here = len(good) + len(obj)
    update = b"xref\n3 1\n%010d 00000 n \ntrailer\n" % len(good)
    update += trailer[:-2] + b" /Prev %d >>\nstartxref\n%d\n%%%%EOF\n" % (prev, here)
    return good + obj + update


def _too_many_objects(good: bytes) -> bytes:
    """x4-good with an incremental update listing 8,388,608 compressed objects, one more than 6.25 allows.

    The entries are in object stream 999, which does not exist; nothing refers to them, so they are listed but never
    read. A PNG Up predictor makes every row after the first the same, so the stream compresses to a few kilobytes.
    """
    with pikepdf.open(io.BytesIO(good)) as pdf:
        size = int(pdf.trailer.Size)
        trailer_id = [bytes(i) for i in pdf.trailer.ID]
        root, info = pdf.Root.objgen[0], pdf.trailer.Info.objgen[0]
    prev = int(good[good.rindex(b"startxref") + 9 :].split()[0])
    count = 8_388_608 - (size - 1)
    xref_num, offset = size + count, len(good)
    rows = bytearray()
    previous = bytes(7)
    entries = [bytes([2]) + (999).to_bytes(3) + i.to_bytes(3) for i in range(count)]
    entries.append(bytes([1]) + offset.to_bytes(3) + bytes(3))
    for row in entries:
        rows.append(2)  # PNG Up
        rows += bytes((a - b) & 0xFF for a, b in zip(row, previous, strict=True))
        previous = row
    data = zlib.compress(bytes(rows), 9)
    ids = "".join(f"<{i.hex()}>" for i in trailer_id)
    head = (
        f"{xref_num} 0 obj\n<< /Type /XRef /Size {xref_num + 1} /W [1 3 3] /Index [{size} {count + 1}] /Prev {prev}"
        f" /Root {root} 0 R /Info {info} 0 R /ID [{ids}] /Filter /FlateDecode"
        f" /DecodeParms << /Predictor 12 /Columns 7 >> /Length {len(data)} >>\nstream\n"
    ).encode()
    return good + head + data + f"\nendstream\nendobj\nstartxref\n{offset}\n%%EOF\n".encode()


def main() -> int:
    parser = argparse.ArgumentParser(description=(__doc__ or "").splitlines()[0])
    parser.add_argument("--check", action="store_true", help="exit 1 if the committed fixtures differ from a rebuild")
    args = parser.parse_args()
    built = render()
    if args.check:
        stale = [
            n
            for n, data in built.items()
            if not (OUT / f"{n}.pdf").is_file() or (OUT / f"{n}.pdf").read_bytes() != data
        ]
        stale += [p.stem for p in OUT.glob("*.pdf") if p.stem not in built and p.stem not in SAMPLES]
        if stale:
            print(f"stale fixtures: {', '.join(sorted(stale))}; run build_pdfs.py", file=sys.stderr)
            return 1
        return 0
    OUT.mkdir(parents=True, exist_ok=True)
    for name, data in built.items():
        (OUT / f"{name}.pdf").write_bytes(data)
    print(f"wrote {len(built)} PDFs to {OUT}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
